"""수용 기본형 승리 좌표를 참고한 Ultimate 의상4표시. 원본/후보 자원은 읽기만."""
from pathlib import Path
import sys,json,argparse
import numpy as np
from PIL import Image
H=Path(__file__).resolve().parent;ROOT=H.parents[2];sys.path.insert(0,str(ROOT))
from native_pose_pack import need,sha,write
from scripts.export_x_consistency import Archive,metrics
def main():
 ap=argparse.ArgumentParser();ap.add_argument('--page',type=int,choices=(1,2),default=1);z=ap.parse_args();refs=(204,205)if z.page==1 else(206,207);d=H/f'ultimate_victory_inputs01/page{z.page:02}';need(not d.exists(),'Fresh input folder')
 pp=H/'prepared_ultimate_hurt02/PL02_U.ARC';bp=H/'prepared_hurt_base01/PL00_U.ARC';need(sha(pp.read_bytes())=='b43e021b70c055d142521d1c679bef323d76b0b30bf27b41c9988815330b2e94','Ultimate input parent changed');need(sha(bp.read_bytes())=='87e7d1db40c2380815ca2986bc27382db73f718d9c338d2eaad776372a2e257b','New base source changed')
 a=Archive(pp.read_bytes());b=Archive(bp.read_bytes());target=Image.new('RGBA',(1536,1024));style=Image.new('RGBA',(1536,1024));old=Image.new('RGBA',(1536,1024));rows=[];crop=(112,124,208,188)
 for row,(form,mask)in enumerate((('before',15),('after',0))):
  for col,n in enumerate(refs):
   pic=b.composite(n,0)[0];cut=pic.crop(crop);need(np.count_nonzero(np.array(cut)[:,:,3])==np.count_nonzero(np.array(pic)[:,:,3]),'New pose crop clips');target.alpha_composite(cut.resize((768,512),Image.Resampling.NEAREST),(col*768,row*512));cur=a.composite(n,mask)[0];cut=cur.crop(crop);need(np.count_nonzero(np.array(cut)[:,:,3])==np.count_nonzero(np.array(cur)[:,:,3]),'Coordinate crop clips');old.alpha_composite(cut.resize((768,512),Image.Resampling.NEAREST),(col*768,row*512));rows.append({'form':form,'ref':n,'new_base_pose_metrics':metrics(pic),'new_base_rgba_sha256':sha(pic.tobytes()),'old_ultimate_metrics':metrics(cur),'old_ultimate_rgba_sha256':sha(cur.tobytes())})
  for col,n in enumerate((0,120,55)):
   pic=a.composite(n,mask)[0];cut=pic.crop((128,128,192,192));need(np.count_nonzero(np.array(cut)[:,:,3])==np.count_nonzero(np.array(pic)[:,:,3]),'Style crop clips');style.alpha_composite(cut.resize((512,512),Image.Resampling.NEAREST),(col*512,row*512))
 d.mkdir(parents=True);target.save(d/'edit_target.png');style.save(d/'accepted_ultimate_style.png');old.save(d/'old_coordinate_reference.png')
 prompt='''Edit Image1, a transparent 1536x1024 game sprite sheet with exactly four 768x512 cells arranged 2 columns by 2 rows. Each cell is a fixed 96x64 logical-pixel canvas enlarged exactly8x, origin (48,36). Image1 is the edit target: newly accepted detailed Shibuki victory poses. Preserve these exact compact body proportions and pose geometry while changing the costume to the corresponding Ultimate costume in Image2. Image2 is the accepted costume and pixel-detail reference, top row jacket, bottom row swimsuit. Image3 is the existing old Ultimate coordinate reference only; do not copy its coarse head or large flat clothing shapes.
Top row: the accepted pale lavender/white short jacket, dark navy collar and cuff shadows, small pink center trim, dark inner swimsuit, bare legs and sandals. Bottom row: the accepted pale lavender one-piece swimsuit with small pink accent, bare shoulders and arms, bare legs and sandals. The bottom row has no jacket sleeves or detached white cuffs. Both costumes must be clearly separated. Same character in all four cells: layered lavender hair and fox ears, gold sunglasses resting on the head as in Image2, small gold ornament, compact face. Replace the base outfit's red bows, red skirt and stocking/boot materials with the correct Ultimate design. Preserve the accepted short, softly rounded proportions, short torso/limbs and full thighs; head including ears stays approximately38percent of the full height, exactly following the reference, never lengthen legs or neck. Maintain the target's head tilt, gaze, hands, elbows, knees, ankles and foot soles. Top and bottom copies of each pose must have the same head/ears, hands, limb joints and stance; only the outfit changes. Keep exact foot positions and hand endpoints inside their own cells.
Use clean readable late-1990s console pixel clusters, small layered hair highlights, ear interiors, visible gold glasses, clear jacket collar/zipper/cuffs and defined swimsuit seams. Match Image2's moderate2-3 tone planes and outline weight. No fuzzy gradients, large featureless purple/white blobs, excessive black scribbles, new glow, particles, props, weapon or additional limbs. Exactly two arms and two legs. Transparent background with no text or labels; keep fixed canvas/cell placement and all transparent margins. Do not resize the whole pose or stretch arms to reach an endpoint.
'''
 if z.page==1:prompt+='Left column204: keep the compact forward/left bent-arm gesture and the other fist at the existing chest/waist level. Right column205: keep one hand raised beside the forehead and the other bent near the torso, matching both target feet and the slight torso angle. Do not flatten the hands into long bars, hide a fist, or turn this into idle.\n'
 else:prompt+='Left column206: keep the folded raised arm beside the head and opposite small fist near the chest. Right column207: keep the same victory motion with the raised fist at the target highest coordinate, without lengthening the upper arm or making the head smaller.\n'
 (d/'prompt.txt').write_text(prompt,'utf8');write(d/'input.json',{'refs':list(refs),'source_layout':{'size':[1536,1024],'native_cell':[96,64],'native_origin':[48,36],'crop':list(crop),'scale':0.125},'ultimate_parent':{'path':pp.relative_to(ROOT).as_posix(),'sha256':sha(pp.read_bytes())},'base_pose_source':{'path':bp.relative_to(ROOT).as_posix(),'sha256':sha(bp.read_bytes())},'rows':rows,'new_body_policy':'수용한 새 기본형 승리의 관절/접지 좌표를 제작 참고로 사용. 원US Ultimate 동일성 주장 아님.','old_native_body_overwrite_allowed':False,'original_game_art_sent':False,'source_generated':False,'files':{p.name:sha(p.read_bytes())for p in d.iterdir()if p.is_file()}});print(d.relative_to(ROOT).as_posix())
if __name__=='__main__':main()
